import sys, subprocess
sys.path.insert(0, '/tmp/probe/py')
from png import decode_png, px
from collections import Counter

WINBG = (40,42,54)

def render(code, lang, out, cfg='/tmp/probe/cfg_black.json'):
    r = subprocess.run(['/workspace/executable','-c',code,'-l',lang,'-o',out,'--silent',
           '--config',cfg,'--scale-factor','1'], capture_output=True, text=True)
    if r.returncode != 0: raise RuntimeError((r.stderr or r.stdout).strip())

def dist(a,b): return sum((x-y)**2 for x,y in zip(a,b))

def calibrate():
    # 40 identical chars, 24 lines -> char width, line pitch, text origin
    code = ('x'*40+'\n')*24
    render(code, 'plain_fallback_check', '/tmp/probe/cal.png') if False else render(code, 'python', '/tmp/probe/cal.png')
    w,h,buf = decode_png('/tmp/probe/cal.png')
    # text pixels = far from winbg
    rows = {}
    cols = {}
    for y in range(h):
        for x in range(w):
            p = px(buf,w,x,y)[:3]
            if dist(p,WINBG) > 3000 and p != (0,0,0):
                rows.setdefault(y,0); rows[y]+=1
                cols.setdefault(x,0); cols[x]+=1
    ys = sorted(rows); xs = sorted(cols)
    # band centers
    bands=[]; prev=None; start=None
    for y in range(h):
        if y in rows:
            if start is None: start=y
            prev=y
        else:
            if start is not None: bands.append((start,prev)); start=None
    if start is not None: bands.append((start,prev))
    centers=[(a+b)/2 for a,b in bands]
    pitch = (centers[-1]-centers[0])/(len(centers)-1)
    cw = (max(xs)-min(xs)+1)/40.0
    print(f"char_width={cw:.4f} x_start={min(xs)} line_pitch={pitch:.4f} band0={bands[0]} n_bands={len(bands)}")
    return cw, min(xs), pitch, bands[0]

def charmap(path, code, cw, x0, pitch, band0):
    w,h,buf = decode_png(path)
    lines = code.rstrip('\n').split('\n')
    ytop = band0[0]
    for li, line in enumerate(lines):
        yc = int(round(band0[0] + li*pitch))
        out=[]
        for ci, ch in enumerate(line):
            xa = int(round(x0 + ci*cw)); xb = int(round(x0 + (ci+1)*cw))
            best=None; bestd=3000
            cnt=Counter()
            for y in range(yc, min(yc+int(pitch), h)):
                for x in range(xa, min(xb,w)):
                    p = px(buf,w,x,y)[:3]
                    d = dist(p,WINBG)
                    if d > 3000 and p!=(0,0,0):
                        cnt[p]+=1
                        if d>bestd: bestd=d; best=p
            if cnt:
                mode = cnt.most_common(1)[0][0]
                out.append((ch, mode, best))
            else:
                out.append((ch, None, None))
        # compress runs
        runs=[]
        for ch,mode,best in out:
            key = mode if mode else best
            if runs and runs[-1][2]==key: runs[-1][1]+=ch
            else: runs.append([ci,ch,key])
        s=''
        for start,chars,key in runs:
            if key is None: s+=f" [{start}:{chars!r}=bg]"
            else: s+=f" [{start}:{chars!r}=#{key[0]:02x}{key[1]:02x}{key[2]:02x}]"
        print(f"L{li+1:2} {line!r}\n    {s}")

if __name__=='__main__':
    cw,x0,pitch,band0 = calibrate()
    print("---")
    lang,srcfile,out = sys.argv[1],sys.argv[2],sys.argv[3]
    code=open(srcfile).read()
    render(code, lang, out)
    charmap(out, code, cw, x0, pitch, band0)
